INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ITA_FAUNUS_VIRGIL','ENT_ITA_FAUNUS','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 7.81-106','Latinus, old and mild, had long possess''d The Latin scepter, and his people blest: His father Faunus; a Laurentian dame His mother; fair Marica was her name. But Faunus came from Picus: Picus drew His birth from Saturn, if records be true. Thus King Latinus, in the third degree, Had Saturn author of his family.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ITA_PICUS_VIRGIL','ENT_ITA_PICUS','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 7.48','But Faunus came from Picus: Picus drew His birth from Saturn, if records be true. Thus King Latinus, in the third degree, Had Saturn author of his family. But this old peaceful prince, as Heav''n decreed, Was blest with no male issue to succeed: His sons in blooming youth were snatch''d by fate; One only daughter heir''d the royal state. Fir''d with her love, and with ambition led, The neighb''ring princes court her nuptial bed.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_APOLLO_VIRGIL','ENT_ROM_APOLLO','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 3.73-98','If Jove assists the passage of our fleet, The third propitious dawn discovers Crete.'' Thus having said, the sacrifices, laid On smoking altars, to the gods he paid: A bull, to Neptune an oblation due, Another bull to bright Apollo slew; A milk-white ewe, the western winds to please, And one coal-black, to calm the stormy seas.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_BACCHUS_VIRGIL','ENT_ROM_BACCHUS','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 6.805','Nor Hercules more lands or labours knew, Not tho'' the brazen-footed hind he slew, Freed Erymanthus from the foaming boar, And dipp''d his arrows in Lernaean gore; Nor Bacchus, turning from his Indian war, By tigers drawn triumphant in his car, From Nisus'' top descending on the plains, With curling vines around his purple reins.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_CERES_VIRGIL','ENT_ROM_CERES','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 4.58-59','Inspir''d with hope, the project they pursue; On ev''ry altar sacrifice renew: A chosen ewe of two years old they pay To Ceres, Bacchus, and the God of Day; Preferring Juno''s pow''r, for Juno ties The nuptial knot and makes the marriage joys. The beauteous queen before her altar stands, And holds the golden goblet in her hands.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_DIANA_VIRGIL','ENT_ROM_DIANA','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 1.498-502, simile for Dido); Cami','"Ho, strangers! have you lately seen," she said, "One of my sisters, like myself array''d, Who cross''d the lawn, or in the forest stray''d? A painted quiver at her back she bore; Varied with spots, a lynx''s hide she wore; And at full cry pursued the tusky boar." Thus Venus: thus her son replied again: "None of your sisters have we heard or seen, O virgin! or what other name you bear Above that style; O more than mortal fair! You','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_MINERVA_VIRGIL','ENT_ROM_MINERVA','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 2.615 confirms her role as destro','"By destiny compell''d, and in despair, The Greeks grew weary of the tedious war, And by Minerva''s aid a fabric rear''d, Which like a steed of monstrous height appear''d: The sides were plank''d with pine; they feign''d it made For their return, and this the vow they paid.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_NEPTUNE_VIRGIL','ENT_ROM_NEPTUNE','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 1.142-156 contains the famous sim','Neptune drives off the winds, and calms the sea. Aeneas, with his own ship and six more, arrives safe at an African port. Venus complains to Jupiter of her son''s misfortunes. Jupiter comforts her, and sends Mercury to procure him a kind reception among the Carthaginians.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_SATURN_VIRGIL','ENT_ROM_SATURN','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 8.319-327','Then Saturn came, who fled the pow''r of Jove, Robb''d of his realms, and banish''d from above. The men, dispers''d on hills, to towns he brought, And laws ordain''d, and civil customs taught, And Latium call''d the land where safe he lay From his unduteous son, and his usurping sway. With his mild empire, peace and plenty came; And hence the golden times deriv''d their name.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_VENUS_VIRGIL','ENT_ROM_VENUS','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 1.314-409','Venus complains to Jupiter of her son''s misfortunes. Jupiter comforts her, and sends Mercury to procure him a kind reception among the Carthaginians. Aeneas, going out to discover the country, meets his mother in the shape of a huntress, who conveys him in a cloud to Carthage, where he sees his friends whom he thought lost, and receives a kind entertainment from the queen.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_VESTA_VIRGIL','ENT_ROM_VESTA','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 2.296-297','Now Troy to thee commends her future state, And gives her gods companions of thy fate: From their assistance walls expect, Which, wand''ring long, at last thou shalt erect.'' He said, and brought me, from their blest abodes, The venerable statues of the gods, With ancient Vesta from the sacred choir, The wreaths and relics of th'' immortal fire.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_ROM_VULCAN_VIRGIL','ENT_ROM_VULCAN','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 8.370-625, the ekphrasis of Roman','Vulcan, at the request of Venus, makes arms for her son Aeneas, and draws on his shield the most memorable actions of his posterity. When Turnus had assembled all his pow''rs, His standard planted on Laurentum''s tow''rs; When now the sprightly trumpet, from afar, Had giv''n the signal of approaching war, Had rous''d the neighing steeds to scour the fields, While the fierce riders clatter''d on their shields; Trembling with rage, th','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1),
('CIT_TRIVIA_VIRGIL','ENT_TRIVIA','SRC_VIRGIL_AENEID','Virgil, Aeneid','Aeneid 6.13, 7.516','Thro'' Trivia''s grove they walk; and now behold, And enter now, the temple roof''d with gold. When Daedalus, to fly the Cretan shore, His heavy limbs on jointed pinions bore, (The first who sail''d in air,) ''tis sung by Fame, To the Cumaean coast at length he came, And here alighting, built this costly frame.','John Dryden',1697,'https://www.gutenberg.org/ebooks/228','https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0055','primary-verbatim',NULL,true,'English verse translation auto-located within the cited Book by name-match; the locus is the Latin line-numbering — consult the original (linked).',DATE '2026-06-17','quote is a verbatim substring of the PD text; located within the cited book by name-anchor + substring gate',1)
